mapper.select:
select ur.id, ur.reporter_id as reporterId, u1.username as reporterName, ur.reported_user_id as reportedUserId, u2.username as reportedUsername, ur.report_time, ur.report_reason, ur.status, ur.reviewer_id, a.username as reviewer_name, ur.review_time, ur.review_result, ur.review_reason from user_report ur left join user u1 on ur.reporter_id = u1.id left join user u2 on ur.reported_user_id = u2.id left join user a on ur.reviewer_id = a.id
and ur.status = #{status}
and ur.reporter_id = #{reporterId}
and ur.reported_user_id = #{reportedUserId}
and ur.reviewer_id = #{reviewerId}
and u1.username like concat('%', #{reporterName}, '%')
order by ur.report_time desc

mapper.update:
update user_report
set status = #{status},
    reviewer_id = #{reviewerId}
where reported_user_id = #{reportedUserId}
  and status = 0
